insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',1,'Língua Portuguesa',null,'O título “Z de depressão” captura, de forma concisa, a ideia central do texto 1. Essa mesma ideia é retomada, de maneira mais detalhada, na seguinte passagem:','{"A": "“Até os 8 anos, levou a vida tranquila de alguém que cresce numa cidade pequena”;", "B": "“Mas então um dos seus tios se matou”;", "C": "“um quadro de adoecimento mental de crianças e jovens brasileiros, com casos repetidos de depressão, ansiedade e síndrome do pânico”;", "D": "“Como as escolas estavam fechadas e seria perigoso realizar as entrevistas presencialmente, só participaram aqueles com conexão à internet”;", "E": "“O Boletim Epidemiológico do Ministério da Saúde não aponta causas exatas do sofrimento mental dos jovens brasileiros”."}'::jsonb,'C',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',2,'Língua Portuguesa',null,'A sequência que funciona como título do texto 1 (“Z de depressão”) é um jogo de palavras, isto é, uma espécie de brincadeira linguística. A força expressiva dessa sequência decorre do fato de que ela:','{"A": "rebate, de maneira assertiva, um comentário hostil sobre a saúde mental dos brasileiros;", "B": "esclarece, de maneira irônica, o significado de uma palavra contida no próprio título;", "C": "observa, de maneira casual, uma contradição inerente ao problema relatado;", "D": "evoca, de maneira implícita, uma outra construção da língua portuguesa;", "E": "oferece, de maneira ponderada, uma solução alternativa para um problema social."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',3,'Língua Portuguesa',null,'O texto 1 se estrutura de forma indutiva, organizando-se do particular (parágrafos 1 e 2) para o geral (parágrafos 3, 4 e 5). Essa mudança do particular para o geral é acompanhada por uma passagem:','{"A": "de um modo de organização narrativo-descritivo para um modo de organização expositivo;", "B": "de um modo de organização descritivo-argumentativo para um modo de organização expositivo;", "C": "de um modo de organização narrativo-injuntivo para um modo de organização argumentativo;", "D": "de um modo de organização narrativo-argumentativo para um modo de organização argumentativo;", "E": "de um modo de organização expositivo-argumentativo para um modo de organização descritivo. Tipo 1 – Branca – Página 4"}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',4,'Língua Portuguesa',null,'“Cresceu encontrando pequenos alívios para a angústia: cachorros, namoradas, bebidas alcoólicas, cortes nos braços.” Nessa passagem, retirada do texto 1, uma enumeração de elementos é encerrada com vírgula – e não, como seria mais usual, com a conjunção aditiva “e”. Nesse contexto, a omissão da conjunção aditiva produz o efeito de:','{"A": "caracterizar um personagem secundário;", "B": "sugerir uma lista não exaustiva;", "C": "expressar uma opinião implícita;", "D": "enunciar uma proposição autoevidente;", "E": "enfatizar uma posição ideológica."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',5,'Língua Portuguesa',null,'“Mas então um dos seus tios se matou, e o menino foi se tornando cada vez mais triste.” A passagem acima, retirada do texto 1, mostra que a conjunção “e” pode veicular ideia de conclusão. Outra passagem do mesmo texto em que essa conjunção apresenta valor conclusivo é:','{"A": "“Ele tem 21 anos e mora em Luz”;", "B": "“Na adolescência, Caio identificou que era um homem transgênero, e sua sensação de isolamento só cresceu”;", "C": "“Em um Boletim Epidemiológico divulgado setembro passado, o Ministério da Saúde apontava que as taxas de suicídio saltaram 116% entre crianças e adolescentes de 5 a 14 anos”;", "D": "“Como as escolas estavam fechadas e seria perigoso realizar as entrevistas presencialmente, só participaram aqueles com conexão à internet”;", "E": "“Ainda assim, os resultados indicaram que a insegurança alimentar esteve associada a maiores níveis de ansiedade e a sintomas depressivos”."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',6,'Língua Portuguesa',null,'“Ainda assim, os resultados indicaram que a insegurança alimentar esteve associada a maiores níveis de ansiedade e a sintomas depressivos.” Nessa passagem, retirada do quarto parágrafo do texto 1, o conector “Ainda assim” indica que a informação subsequente irá contrariar uma expectativa do leitor. A alternativa em que essa expectativa contrariada está formulada de modo adequado é:','{"A": "a geração Z, por ser formada por pessoas atualmente jovens, tenderá a não sofrer problemas de saúde mental;", "B": "pessoas trans, por terem poucas informações sobre a própria condição, são mais vulneráveis a ansiedade e depressão;", "C": "a insegurança alimentar, por ser própria de países em desenvolvimento, tenderá a ser detectada em estudos sobre a realidade brasileira;", "D": "dados de pesquisas, por serem enviesados, tendem a distorcer a realidade;", "E": "pessoas mais pobres, por terem menos acesso à internet, não terão seus problemas econômicos refletidos na pesquisa."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',7,'Língua Portuguesa',null,'“Virou alvo de bullying na escola, perdeu os amigos – ‘não sobrou ninguém’, ele conta. Aos 10 anos, tentou suicídio e precisou ser internado às pressas.” A proposta de adaptação dessa passagem do texto 1 em que o trecho em discurso direto está corretamente transposto para o discurso indireto livre é:','{"A": "Virou alvo de bullying na escola, perdeu os amigos – “não sobrou ninguém”, conta ele. Aos 10 anos, tentou suicídio e precisou ser internado às pressas;", "B": "Virou alvo de bullying na escola, perdeu os amigos. Ele conta: “não sobrou ninguém”. Aos 10 anos, tentou suicídio e precisou ser internado às pressas;", "C": "Virou alvo de bullying na escola, perdeu os amigos. Quando se deu conta, tomou um susto. Não havia sobrado ninguém. Aos 10 anos, tentou suicídio e precisou ser internado às pressas;", "D": "Virou alvo de bullying na escola, perdeu os amigos. Ele conta que não sobrou ninguém. Aos 10 anos, tentou suicídio e precisou ser internado às pressas;", "E": "Virou alvo de bullying na escola, perdeu os amigos. Ele contou que não sobrara ninguém. Aos 10 anos, tentou suicídio e precisou ser internado às pressas."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',8,'Língua Portuguesa',null,'“Na adolescência, Caio identificou que era um homem transgênero, e sua sensação de isolamento só cresceu. Com o agravamento do quadro depressivo, foi levado ao hospital algumas vezes depois de se automutilar. Embora os médicos tenham recomendado, ele nunca tratou a depressão por um longo período de tempo. [...]” Essa passagem, retirada do texto 1, pode ser reescrita, sem modificação do sentido original e sem desvio em relação à norma padrão do português, da seguinte forma:','{"A": "Na adolescência, Caio identificou que era um homem transgênero, e sua sensação de isolamento só cresceu. Em função do agravamento do quadro depressivo, foi levado ao hospital algumas vezes depois de se automutilar. Ainda que os médicos tenham recomendado, ele nunca tratou a depressão por um longo período de tempo. [...];", "B": "Caio identificou na adolescência, que era um homem transgênero, e sua sensação de isolamento só cresceu. Com o agravamento do quadro depressivo, foi levado ao hospital algumas vezes depois de se automutilar. Ainda que os médicos tenham recomendado, ele nunca tratou a depressão por um longo período de tempo. [...];", "C": "Na adolescência, Caio descobriu que era um homem transgênero, razão pela qual, sua sensação de isolamento só cresceu. Com o agravamento do quadro depressivo, foi levado ao hospital algumas vezes depois de se automutilar. Mesmo os médicos tendo recomendado, ele nunca tratou a depressão, por um longo período de tempo. [...];", "D": "Caio na adolescência, identificou ser um homem transgênero, e sua sensação de isolamento só cresceu. Não obstante o agravamento do seu quadro depressivo, foi levado ao hospital algumas vezes depois de se automutilar. Embora os médicos tenham recomendado, ele nunca tratou a depressão por um longo período de tempo. [...];", "E": "Na adolescência, Caio identificou que era um homem transgênero, o que implicou no crescimento da sua sensação de isolamento. Com o agravamento do quadro depressivo, foi levado ao hospital algumas vezes depois de se automutilar. Embora os médicos tenham recomendado, ele nunca tratou a depressão por um longo período de tempo. [...]. Tipo 1 – Branca – Página 5"}'::jsonb,'A',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',9,'Língua Portuguesa',null,'“Os dados levaram o governo federal a classificar o suicídio como ‘um problema de saúde pública crescente no Brasil, com destaque aos grupos etários mais jovens’.” Essa passagem, retirada do texto 1, pode ser reescrita de diversas maneiras. A reescritura em que NÃO se verifica nenhum erro relativo ao acento indicativo de crase é:','{"A": "Face a esses dados, o governo federal classificou o suicídio como um problema de saúde pública crescente no Brasil, com destaque as faixas etárias mais jovens;", "B": "Os dados levaram a classificação do suicídio, por parte do governo federal, como um problema de saúde pública crescente no Brasil, com destaque aos grupos etários mais jovens;", "C": "Em reação a esses dados, o governo federal procedeu à classificação do suicídio como um problema de saúde pública crescente no Brasil, sobretudo no que se refere às faixas etárias mais jovens;", "D": "Face à informações como essas, o governo federal passou a tratar o suicídio como um problema de saúde pública crescente no Brasil, com destaque aos grupos etários mais jovens;", "E": "Reagindo as descobertas do Boletim Epidemiológico, o governo federal passou à classificar o suicídio como um problema de saúde pública crescente no Brasil, com destaque aos grupos etários mais jovens."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',10,'Língua Portuguesa','Texto 2 A nova era do divórcio (fragmento) “‘Novelas da Globo aumentam o número de divórcios no Brasil.’ Parece fake news de haters, mas não. Trata-se de um dado histórico. A conclusão é de um estudo de 2009, feito pelo Banco Interamericano de Desenvolvimento (BID). A pesquisa fez um cruzamento entre informações de censos das décadas de 1970, 1980 e 1990 e dados sobre a expansão do sinal da Globo no país. Segundo os autores do estudo, o número de mulheres que se separaram aumentou conforme a teledramaturgia da emissora foi chegando a mais cidades. ‘A exposição a estilos de vida modernos mostrados na TV, a funções desempenhadas por mulheres emancipadas e a uma crítica aos valores tradicionais mostrou estar associada aos aumentos nas frações de mulheres separadas e divorciadas nas áreas municipais brasileiras’, diz a pesquisa. [...] O que os estudiosos do BID não poderiam prever é o quanto os divórcios aumentariam no Brasil do século 21, por um motivo ainda mais insuspeito: a disseminação de um vírus. Segundo o Colégio Notarial do Brasil, que congrega os tabeliães de notas e protestos, no primeiro ano da pandemia, em 2020, houve um aumento de 15% no número de divórcios em comparação com o ano anterior. Em 2021, então, o número de casais que oficializaram a separação bateu recorde: 80.573 divórcios consensuais, o maior da série histórica, que é registrada desde 2007. [...] Sim, o início desnorteante da pandemia foi o gatilho para um boom de divórcios planeta afora. Motivos para a escalada nas tensões entre casais não faltaram, você sabe: o encarceramento no lar de ambos os cônjuges (condição que se estendeu indefinidamente para quem aderiu ao home office), perrengues financeiros, a necessidade de lidar com as crianças estudando em casa, distúrbios psicológicos (ansiedade, depressão, paranoia…). [...] A [empresa americana] Legal Templates mostrou que os casados há menos de cinco anos foram os que mais se separaram em 2020: 58%. Aliás, quanto menor o tempo de união oficial, maior o aumento no índice de cada um para o seu lado. Enquanto, em 2019, pré-Covid, apenas 11% dos que se separaram tinham menos de cinco meses sob o mesmo teto, em 2020 essa porcentagem quase dobrou: foi para 20%. Estudiosos que analisaram esses dados chegaram a uma conclusão que faz sentido: casais que haviam se unido havia pouco tempo são menos calejados para enfrentar o maremoto que atingiu a praia conjugal na onda do vírus. Os parceiros mais longevos já tinham passado por outras crises. Talvez ilesos, talvez feridos. E muitos aprenderam a sair delas juntos. [...] Nesta nova era do divórcio, vale um alerta: mesmo nas separações mais amigáveis – e até afetuosas –, romper um relacionamento de anos segue sendo tão difícil quanto sempre foi. Os primeiros tempos tendem a ser um período deprimente, de luto mesmo, acordos difíceis e de pisar em ovos. Se você se separou, vale a pena um esforço a mais para manter o bom convívio. Não apenas pelo bem dos filhos – se o casamento produziu crianças. É importante honrar uma história que, em boa parte do tempo, foi partilhada com a pessoa que um dia você amou como se fosse a única.” Disponível em: https://super.abril.com.br/comportamento/a-nova-era-do-divorcio. Acesso em: 24/07/2022 Tipo 1 – Branca – Página 6','É possível identificar, no texto 2, três blocos estruturais simétricos: um primeiro formado pelos parágrafos 1 e 2; um segundo formado pelos parágrafos 4 e 5; e um terceiro formado pelos parágrafos 6 e 7. Como a organização é paralelística, os primeiros parágrafos de cada par (isto é, os parágrafos 1, 4 e 6) desempenham sempre uma mesma função textual, assim como os segundos parágrafos de cada par (isto é, os parágrafos 2, 5 e 7). As funções textuais desempenhadas pelos parágrafos 1, 4 e 6, de um lado, e 2, 5 e 7, de outro, estão corretamente caracterizadas, respectivamente, na seguinte alternativa:','{"A": "veicular um enunciado irônico e refutar opiniões contrárias;", "B": "estabelecer uma correlação e fornecer a causa subjacente;", "C": "levantar uma hipótese e enumerar suas consequências imediatas;", "D": "caracterizar uma situação e narrar os eventos decorrentes;", "E": "enfatizar um problema e propor uma solução concreta."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',11,'Língua Portuguesa',null,'O texto 2 elenca diversos fatores relacionados ao aumento de casos de divórcio. Esses fatores podem ser divididos em três grupos: causas indiretas (ou mediatas), causas diretas (ou imediatas) e facilitadores. A alternativa que apresenta, respectivamente, uma causa indireta, uma causa direta e um facilitador é:','{"A": "expansão do sinal da Rede Globo, exposição de estilos de vida modernos e encarceramento de ambos os cônjuges;", "B": "encarceramento de ambos os cônjuges, perrengues financeiros e necessidade de lidar com crianças estudando em casa;", "C": "distúrbios psicológicos, falta de experiência com crises prévias e críticas aos valores tradicionais;", "D": "pandemia de Covid-19, encarceramento de ambos os cônjuges e pouco tempo de casamento;", "E": "exposição de funções desempenhadas por mulheres emancipadas, pandemia de Covid-19 e adesão ao home office."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',12,'Língua Portuguesa',null,'O último parágrafo do texto 2 recorre a uma estratégia de construção textual bastante comum em parágrafos de conclusão de reportagens de divulgação científica. Essa estratégia consiste na adoção:','{"A": "do subjuntivo como modo verbal predominante, com o objetivo de relatar eventos hipotéticos;", "B": "de conjunções causais, com o objetivo de estabelecer relações lógicas de causa e efeito;", "C": "de substantivos ligados ao jargão acadêmico, com o objetivo de conferir credibilidade ao texto;", "D": "de um registro fortemente irônico, com o objetivo de provocar surpresa no leitor;", "E": "da injunção como tipo textual primário, com o objetivo de aconselhar o leitor."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',13,'Língua Portuguesa',null,'“O que os estudiosos do BID não poderiam prever é o quanto os divórcios aumentariam no Brasil do século 21, por um motivo ainda mais insuspeito: a disseminação de um vírus.” Retirado do texto 2, esse fragmento sugere, implicitamente, que a correlação entre aumento do número de divórcios e expansão do sinal da Rede Globo é insuspeita. Essa mesma ideia pode ser flagrada na seguinte passagem:','{"A": "“Parece fake news”;", "B": "“Trata-se de um dado histórico”;", "C": "“o número de mulheres que se separaram aumentou”;", "D": "“A exposição a estilos de vida modernos mostrados na TV”;", "E": "“aumentos nas frações de mulheres separadas e divorciadas nas áreas municipais brasileiras”."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',14,'Língua Portuguesa',null,'“A [empresa americana] Legal Templates mostrou que os casados há menos de cinco anos foram os que mais se separaram em 2020: 58%. Aliás, quanto menor o tempo de união oficial, maior o aumento no índice de cada um para o seu lado.” Na passagem acima, retirada do texto 2, o conector “aliás”, ao mesmo tempo em que contribui para a coesão textual, introduz uma sequência que desempenha a função de:','{"A": "corrigir um erro;", "B": "estabelecer uma generalização;", "C": "explicitar uma contradição;", "D": "resumir uma explicação;", "E": "avaliar uma proposta."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',15,'Língua Portuguesa',null,'“Segundo o Colégio Notarial do Brasil, que congrega os tabeliães de notas e protestos, no primeiro ano da pandemia, em 2020, houve um aumento de 15% no número de divórcios em comparação com o ano anterior. Em 2021, então, o número de casais que oficializaram a separação bateu recorde [...]” Muitas gramáticas ensinam que o “então” é uma conjunção conclusiva. No entanto, na passagem acima, retirada do texto 2, essa palavra apresenta um uso distinto, que é próprio do registro informal e não costuma figurar nos compêndios gramaticais. Esse mesmo uso está presente no seguinte exemplo:','{"A": "Eu estava meio triste, então resolvi ficar em casa.", "B": " Você já tem uma resposta pra mim?  Então... eu já pensei bastante, mas ainda não sei o que responder.", "C": " Então, vamos?", "D": "Até então, eu ainda não havia tomado uma decisão.", "E": "Se você acha que 50 convidados é muita gente, 100, então, nem se fala. Tipo 1 – Branca – Página 7"}'::jsonb,'E',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',16,'Língua Portuguesa',null,'“Os primeiros tempos tendem a ser um período deprimente, de luto mesmo, acordos difíceis e de pisar em ovos.” Essa passagem, retirada do texto 2, apresenta uma marca de informalidade. A proposta de reescritura em que essa marca é substituída por uma palavra ou expressão mais formal sem que haja alteração substancial de significado é:','{"A": "Os primeiros tempos são, em geral, um período deprimente, de luto mesmo, acordos difíceis e de pisar em ovos;", "B": "Os primeiros anos tendem a ser um período deprimente, de enlutamento mesmo, acordos difíceis e de pisar em ovos;", "C": "Os primeiros tempos tendem a ser um período deprimente, de luto mesmo, pactos difíceis e de pisar em ovos;", "D": "Os primeiros tempos tendem a ser um período deprimente, de luto mesmo, acordos complexos e de pisar em ovos;", "E": "Os primeiros tempos tendem a ser um período deprimente, de luto mesmo, acordos complexos e atitudes cautelosas."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',17,'Língua Portuguesa',null,'Em cada uma das alternativas abaixo, encontra-se, nesta ordem, uma passagem transcrita do texto 2 e uma proposta de reescritura dessa mesma passagem. Assinale a alternativa na qual, ao mesmo tempo, a passagem transcrita do texto 2 seja ambígua (desconsiderando-se nosso conhecimento de mundo) e a proposta de reescritura apresentada desfaça essa ambiguidade:','{"A": "“Em 2021, então, o número de casais que oficializaram a separação bateu recorde” / Em 2021, então, bateu recorde o número de casais que oficializaram a separação;", "B": "“Estudiosos que analisaram esses dados chegaram a uma conclusão que faz sentido” / Analisando esses dados, estudiosos chegaram a uma conclusão que faz sentido;", "C": "“O que os estudiosos do BID não poderiam prever é o quanto os divórcios aumentariam no Brasil do século 21” / O que os estudiosos do BID não poderiam prever, no Brasil do século 21, é o quanto os divórcios aumentariam;", "D": "“[...] o encarceramento no lar de ambos os cônjuges (condição que se estendeu indefinidamente para quem aderiu ao home office) [...]” / o encarceramento de ambos os cônjuges no lar (condição que se estendeu indefinidamente para quem aderiu ao home office);", "E": "“Segundo os autores do estudo, o número de mulheres que se separaram aumentou conforme a teledramaturgia da emissora foi chegando a mais cidades” / De acordo com os autores do estudo, o número de mulheres que se separaram aumentou conforme a teledramaturgia da emissora foi chegando a mais cidades."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',18,'Língua Portuguesa',null,'Embora tanto o texto 1 quanto o texto 2 pertençam ao gênero textual reportagem, o segundo exibe uma linguagem mais informal que o primeiro. Essa maior informalidade é evidenciada pela presença, no texto 2, de:','{"A": "estrangeirismos recentes e marcas de interlocução direta;", "B": "orações subordinadas adjetivas e discurso indireto livre;", "C": "gírias associadas à fala jovem e paralelismos sintáticos;", "D": "frases nominais e abreviações;", "E": "regionalismos e verbos impessoais."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',19,'Língua Portuguesa',null,'Embora os textos 1 e 2 pertençam ao gênero textual reportagem, eles correspondem a subgêneros distintos. Em particular, apenas o texto 2 se qualifica como uma reportagem de divulgação científica. Um reflexo dessa especificidade é o fato de que apenas o texto 2 inclui metáforas criativas (isto é, inovadoras, não convencionalizadas), como pode ser visto na seguinte passagem:','{"A": "“‘Novelas da Globo aumentam o número de divórcios no Brasil’”;", "B": "“A conclusão é de um estudo de 2009, feito pelo Banco Interamericano de Desenvolvimento (BID)”;", "C": "“A [empresa americana] Legal Templates mostrou que os casados há menos de cinco anos foram os que mais se separaram em 2020”;", "D": "“[...] casais que haviam se unido havia pouco tempo são menos calejados para enfrentar o maremoto que atingiu a praia conjugal na onda do vírus”;", "E": "“[...] mesmo nas separações mais amigáveis – e até afetuosas , romper um relacionamento de anos segue sendo tão difícil quanto sempre foi”."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',20,'Língua Portuguesa',null,'“O Boletim Epidemiológico do Ministério da Saúde não aponta causas exatas do sofrimento mental dos jovens brasileiros, mas dá a entender que certas particularidades ajudariam a explicar o aumento das taxas de suicídio juvenil.” “O que os estudiosos do BID não poderiam prever é o quanto os divórcios aumentariam no Brasil do século 21.” Nessas passagens, retiradas respectivamente dos textos 1 e 2, as duas formas verbais sublinhadas se encontram no futuro do pretérito. Apesar disso, é possível observar que esse tempo verbal desempenha funções comunicativas distintas em cada um dos casos. As funções comunicativas desempenhadas pelo futuro do pretérito nas passagens acima estão corretamente caracterizadas, respectivamente, em:','{"A": "expressar ordem ou pedido e enfatizar a noção de desejo;", "B": "marcar polidez no intercâmbio conversacional e indicar que o fato expresso é dependente de uma condição;", "C": "sinalizar incerteza em relação à informação expressa e indicar um evento futuro em relação a um tempo passado;", "D": "exprimir uma verdade atemporal e destacar o caráter improvável de uma condição;", "E": "enfatizar um questionamento e sugerir ausência de comprometimento em relação a uma determinada posição. Tipo 1 – Branca – Página 8 Legislação Específica"}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',21,'Direito Administrativo',null,'João, servidor público há mais de uma década, ocupante de cargo de provimento efetivo em determinada estrutura de poder no Estado do Tocantins, foi acusado e condenado, em processo administrativo, pela prática de grave infração disciplinar, o que culminou na sua demissão. Irresignado com a demissão, João ingressou com medida judicial buscando a sua anulação, no que obteve êxito, sendo acolhido o argumento de que as provas utilizadas eram nulas. Considerando os dados da narrativa, deve ser aplicado a João o instituto da:','{"A": "reversão;", "B": "recondução;", "C": "reintegração;", "D": "readaptação;", "E": "disponibilidade."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',22,'Direito Administrativo',null,'Ao analisar a possível competência do Tribunal de Contas do Estado do Tocantins, em relação às operações de crédito a serem realizadas pelo Governo do Estado, João concluiu corretamente que essa atuação era não só necessária, como de indiscutível relevância. Ato contínuo, consultou Pedro a respeito do iter procedimental a ser observado e do seu alcance, sendo-lhe corretamente respondido que:','{"A": "após a solicitação encaminhada pelo Governo, ao Poder Legislativo, para a realização da operação, o Tribunal de Contas emitirá parecer sobre a sua legalidade, legitimidade, economicidade e razoabilidade;", "B": "o Governo deve solicitar a análise inicial ao Tribunal de Contas, que emitirá parecer sobre a legalidade, legitimidade, economicidade e razoabilidade da operação, encaminhando-o ao Poder Legislativo para a decisão final;", "C": "após a solicitação encaminhada pelo Governo, ao Poder Legislativo, para a concretização da operação, o Tribunal de Contas decidirá sobre a sua realização, ou não, considerando a legalidade, legitimidade, economicidade e razoabilidade;", "D": "o Governo deve solicitar a análise inicial ao Tribunal de Contas, que decidirá sobre a legalidade, legitimidade, economicidade e razoabilidade da operação, encaminhando a decisão ao Poder Legislativo, que avaliará a sua conveniência;", "E": "após a solicitação encaminhada pelo Governo, ao Poder Legislativo, para a realização da operação, o Tribunal de Contas emitirá parecer apenas sobre a sua legalidade, cabendo ao Legislativo a análise de legitimidade, economicidade e razoabilidade."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',23,'Direito Administrativo',null,'Joana, recém-ingressa no quadro de servidores do Tribunal de Contas do Estado do Tocantins, analisou o rol de medidas cautelares passíveis de serem adotadas por esse Tribunal, sem necessidade de intervenção do Poder Judiciário. Em sua análise preliminar, chegou à conclusão de que essas medidas seriam: 1. o arresto de bens; 2. o afastamento temporário do dirigente do órgão ou entidade; 3. a exibição de documentos ou dados e bens; e 4. a produção antecipada de provas. Ao se deparar com as conclusões de Joana, Maria, sua colega de setor, observou, corretamente, que não depende(m) da atuação do Poder Judiciário:','{"A": "somente a medida 3;", "B": "somente a medida 4;", "C": "somente as medidas 1 e 2;", "D": "somente as medidas 2, 3 e 4;", "E": "as medidas 1, 2, 3 e 4."}'::jsonb,'D',true,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',24,'Direito Administrativo',null,'Maria, embora tivesse nível superior, foi aprovada em concurso público e tomou posse em cargo de provimento efetivo de nível médio do Tribunal de Contas do Estado do Tocantins. À luz do Plano de Cargos, Carreiras e Remuneração dos Servidores do Tribunal de Contas do Estado do Tocantins, Maria tem assegurado o direito:','{"A": "à percepção de adicional de qualificação;", "B": "à percepção de adicional de nível superior;", "C": "ao enquadramento na classe que congrega os cargos de nível superior;", "D": "ao enquadramento na classe imediatamente superior àquela em que se encontra;", "E": "ao enquadramento no padrão imediatamente superior, na classe em que se encontra."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',25,'Direito Administrativo',null,'Pedro, servidor do Tribunal de Contas do Estado do Tocantins, durante uma fiscalização, suspeitou que Maria teria sonegado um documento que seria útil à análise a ser realizada pela equipe de fiscalização. Por tal razão, alertou-a das sanções aplicáveis em virtude de sonegação de processo, documento ou informação e obstrução ao livre exercício das atividades de controle externo. Irresignada com a suspeita de Pedro e com o “alerta” que recebera, solicitou que o seu advogado analisasse a compatibilidade dessa conduta com o Código de Ética dos Servidores do Tribunal de Contas do Estado do Tocantins. Foi corretamente respondido a Maria que Pedro agiu em:','{"A": "desacordo com o referido Código, pois deve observar um padrão de discrição na solicitação de documentos;", "B": "harmonia com o referido Código, pois deve fazer alertas dessa natureza, ao fiscalizado, quando necessário;", "C": "desacordo com o referido Código, pois deve manter-se neutro em relação à postura do fiscalizado no decorrer dos trabalhos;", "D": "desacordo com o referido Código, pois somente deve agir em harmonia com juízos de certeza, não com a suposição característica da mera suspeita;", "E": "harmonia com o referido Código, pois deve agir de modo inquisitorial em relação ao fiscalizado, em razão da superior hierarquia do controle externo. Tipo 1 – Branca – Página 9 Noções de Direito"}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',26,'Direito Administrativo',null,'O regime jurídico dos servidores públicos do Estado Alfa foi alterado pela Lei nº XX/2020, sendo assegurado determinado benefício pecuniário, de caráter episódico, não contínuo, aos servidores que preenchessem os requisitos objetivos previstos na norma. Dois anos depois, ao ser advertido do crescimento exponencial das despesas com pessoal, o que fora parcialmente influenciado pela criação do referido benefício, o chefe do Poder Executivo apresentou projeto de lei, que resultou na Lei nº YY/2022, extinguindo-o. Após a extinção do benefício, Pedro, pessoa muito distraída, percebeu que preenchera os requisitos para a fruição do benefício, mas não apresentara o requerimento pertinente. Ao procurar um advogado, foi informado, corretamente, que:','{"A": "pode requerer a fruição do benefício, observado o prazo prescricional afeto à Fazenda Pública, pois, uma vez inserido no regime jurídico dos servidores, é vedada a supressão por lei posterior, sob pena de afronta ao direito adquirido;", "B": "não pode requerer a fruição do benefício, salvo se a Lei nº YY/2022 assegurou a sua fruição àqueles que não o tenham requerido em momento anterior, os quais tinham mera expectativa de direito;", "C": "não pode requerer a fruição do benefício, já que a pretensão administrativa deve ser apresentada de modo contemporâneo ao direito, pois um não pode subsistir dissociado do outro;", "D": "não pode requerer a fruição do benefício, já que a despesa pública está relacionada à previsão orçamentária, que não pode satisfazer benefícios relativos a exercícios pretéritos;", "E": "pode requerer a fruição do benefício, observado o prazo prescricional afeto à Fazenda Pública, pois tem o direito adquirido à sua fruição."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',27,'Direito Administrativo',null,'Laura, diretora de recursos humanos na Secretaria de Educação do Estado Alfa, foi informada de que três atos administrativos exarados em seu setor foram objeto de alteração: (1) o primeiro foi considerado, pela autoridade hierarquicamente superior, incompatível com o interesse público, o que a levou a substituí-lo por ato de teor diverso; (2) o segundo teve identificado um vício de finalidade, sendo determinada a cessação dos seus efeitos pela autoridade competente; e (3) o terceiro padecia de vício de competência, mas a autoridade competente aquiesceu com os seus termos, subscrevendo-o. Os acontecimentos descritos em 1, 2 e 3 refletem, respectivamente, os institutos da:','{"A": "anulação, revogação e retificação;", "B": "revogação, invalidação e convalidação;", "C": "invalidação, revogação e confirmação;", "D": "invalidação, contraposição e ratificação;", "E": "revogação, retificação e retirada hierárquica."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',28,'Direito Administrativo',null,'Determinada repartição pública estadual tinha em seu poder informações a respeito da filiação partidária de Joana, a qual fora declinada para fins de verificação da presença, ou não, de impedimento ao exercício de determinada função pública. Em razão das características desse dado, o responsável pela repartição consultou sua assessoria a respeito de sua natureza e sobre a possibilidade desse dado ser submetido a tratamento, com o objetivo de serem realizados estudos por órgão de pesquisa. A assessoria respondeu, corretamente, que se está perante dado:','{"A": "consentido, já que fornecido voluntariamente por Joana, o que afasta a necessidade de nova autorização para o respectivo tratamento;", "B": "pessoal sensível, não sendo necessário o fornecimento de consentimento do titular para tratamento, caso seja indispensável à realização da referida finalidade;", "C": "anonimizado, pois originário da relação funcional, tendo se incorporado à base de dados administrativa e não carecendo de consentimento do titular para a sua utilização;", "D": "público, pois originário da relação funcional, tendo se incorporado à base de dados administrativa e não carecendo de consentimento do titular para a sua utilização;", "E": "pessoal, sendo imprescindível o fornecimento de consentimento do titular para a realização de qualquer tratamento, inclusive para os fins descritos na narrativa."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',29,'Direito Administrativo',null,'Adalto, diretor de licitações no âmbito do Poder Executivo do Estado Alfa, recebeu comunicação de que esse ente federativo almejava realizar operação de crédito interno, havendo dúvida em relação à modalidade de procedimento licitatório a ser observado, considerando os balizamentos estabelecidos pela Lei nº 14.133/2021, que vinha sendo observada pela generalidade dos órgãos dessa estrutura de poder. À luz dessa narrativa, Adalto concluiu, corretamente, em razão do disposto na Lei nº 14.133/2021, que o contrato que verse sobre o referido objeto:','{"A": "não está sujeito ao regime do referido diploma normativo;", "B": "deve ser antecedido de licitação na modalidade de diálogo competitivo;", "C": "deve ser antecedido de licitação na modalidade de concorrência;", "D": "não precisa ser antecedido de licitação, que é dispensável, estando adstrito, apenas, aos balizamentos incidentes sobre o contrato administrativo;", "E": "não precisa ser antecedido de licitação, que é inexigível, estando adstrito, apenas, aos balizamentos incidentes sobre o contrato administrativo. Tipo 1 – Branca – Página 10"}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',30,'Direito Administrativo',null,'O Tribunal de Contas do Estado do Tocantins, em decisão transitada em julgado, rejeitou as contas apresentadas por João, ordenador de despesas no Município Alfa. Com isso, imputou-lhe um débito, além da aplicação de multa. Irresignado com a decisão, João consultou o seu advogado sobre a existência de alguma medida, a ser manejada no âmbito do próprio Tribunal, para que a decisão fosse alterada, já que, a seu ver, ocorrera um manifesto erro de cálculo nas contas. O advogado respondeu, corretamente, que:','{"A": "estavam exauridas as medidas passíveis de serem adotadas no âmbito do Tribunal de Contas;", "B": "pode ser proposta a ação de revisão, a ser manejada no biênio subsequente ao trânsito em julgado da decisão;", "C": "é cabível o pedido de reexame, a qualquer tempo, desde que baseado em perícia contábil, indicativa do erro de cálculo alvitrado por João;", "D": "é cabível a ação rescisória, a ser manejada nos cinco anos subsequentes ao trânsito em julgado da decisão, sendo facultada a produção de novas provas;", "E": "embora seja prevista a possibilidade de ser proposta ação rescisória contra decisões transitadas em julgado, ela só seria cabível em se tratando de falsidade de documentos."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',31,'Direito Administrativo',null,'O governador do Estado Alfa apresentou à Assembleia Legislativa o projeto de lei orçamentária anual. Após as discussões no âmbito da Comissão de Orçamento e Finanças, deliberou-se pela aprovação de diversas emendas individuais que buscavam viabilizar o desenvolvimento de determinada política pública. Apesar dessas emendas serem plenamente compatíveis com o plano plurianual e a lei de diretrizes orçamentárias, surgiram dúvidas em relação à origem dos recursos a serem utilizados. Após analisar as opções jurídica e politicamente viáveis, o presidente da Comissão observou, corretamente, que esses recursos poderiam resultar de anulação de despesas associadas:','{"A": "às dotações relativas à contribuição previdenciária;", "B": "às transferências voluntárias para os Municípios;", "C": "aos benefícios contínuos devidos aos servidores;", "D": "aos juros devidos em razão da dívida pública;", "E": "às transferências tributárias constitucionais."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',32,'Direito Administrativo',null,'O chefe do Poder Executivo do Estado Beta, em cujo território estava localizado o Município Alfa, almejava realizar uma transferência voluntária de recursos para esse ente federativo com o fim de viabilizar a realização de objetivos de interesse comum e amenizar os efeitos da grave crise financeira que assolava a municipalidade, cujo potencial turístico fora afetado por fortes chuvas. Ao analisar a arrecadação tributária do Município Alfa, que se mostrava elevada e supria suas despesas regulares, isto em momento anterior às fortes chuvas, a Procuradoria do Estado constatou que, por decisão das maiorias ocasionais, esse ente federativo não tinha instituído: (1) o imposto de transmissão inter vivos, a qualquer título, por ato oneroso, de bens imóveis; (2) nenhuma contribuição de melhoria, embora já tivesse realizado diversas obras públicas que poderiam justificá-la; e (3) a taxa associada ao recolhimento de lixo. Considerando a sistemática estabelecida pela Lei Complementar nº 101/2000, é correto afirmar que:','{"A": "a presença das situações descritas em 1, 2 e 3 é requisito indispensável à realização de transferências voluntárias pelo Estado Beta ao Município Alfa;", "B": "as situações descritas em 1, 2 e 3 acarretam, como consequência, a impossibilidade de ser realizada a transferência voluntária alvitrada;", "C": "apenas a situação descrita em 2 acarreta, como consequência, a impossibilidade de ser realizada a transferência voluntária alvitrada;", "D": "apenas a situação descrita em 1 acarreta, como consequência, a impossibilidade de ser realizada a transferência voluntária alvitrada;", "E": "as situações descritas em 1, 2 e 3 são projeções da autonomia política do Município Alfa, não constituindo óbice à realização de transferência voluntária pelo Estado Beta."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',33,'Direito Administrativo',null,'Em auditoria realizada pelo Tribunal de Contas do Estado do Tocantins, no âmbito de determinada estrutura estatal de poder, foi constatada a inexistência de comprovação de vultosas despesas realizadas na referida estrutura, sendo fortes os indícios de que os recursos públicos foram desviados e de que os atos ilícitos terão continuidade se o servidor público responsável pela estrutura não for cautelarmente afastado. O referido afastamento:','{"A": "pode ser promovido, em caráter temporário, pelo Tribunal de Contas, de ofício ou a requerimento do Ministério Público especial;", "B": "pode ser promovido, em caráter definitivo, pelo Tribunal de Contas, mas apenas se houver requerimento do Ministério Público especial;", "C": "não pode ser promovido, mesmo em caráter temporário, em momento anterior à decisão definitiva do Tribunal de Contas, o que decorre da presunção de inocência;", "D": "não pode ser promovido pelo Tribunal de Contas, apenas pelo Poder Judiciário, em caráter temporário, o que pressupõe requerimento do Ministério Público comum;", "E": "não pode ser promovido pelo Tribunal de Contas, apenas pelo Poder Judiciário, em caráter definitivo ou temporário, o que pressupõe requerimento do Ministério Público, especial ou comum. Tipo 1 – Branca – Página 11"}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',34,'Direito Administrativo',null,'Após amplos debates entre seus membros, o Tribunal de Justiça do Estado Alfa apresentou uma proposição à Assembleia Legislativa, veiculando o Estatuto da Magistratura do Estado Alfa. Ato contínuo, diversos parlamentares argumentaram com a inconstitucionalidade formal da respectiva proposição. O relator da matéria no âmbito da Comissão de Constituição e Justiça, após analisar os argumentos apresentados, concluiu, corretamente, que:','{"A": "a forma federativa de Estado autoriza que o Poder Judiciário de cada ente tenha o seu Estatuto, observados, sempre, os balizamentos estabelecidos pela Constituição da República de 1988;", "B": "a proposição somente será constitucional se tiver a forma de proposta de emenda constitucional, que observará os balizamentos estabelecidos pela Constituição da República de 1988;", "C": "o Estatuto da Magistratura tem sede exclusivamente constitucional, não sendo possível que a legislação infraconstitucional, federal ou estadual, trate da matéria;", "D": "a proposição somente será constitucional se tiver a forma de projeto de lei complementar, que complementará as normas estabelecidas pelo Estatuto Nacional da Magistratura;", "E": "a proposição é inconstitucional, já que a Constituição da República de 1988 somente dispõe sobre a existência do Estatuto Nacional da Magistratura."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',35,'Direito Administrativo',null,'Maria, servidora pública que, há cerca de dez anos, ocupava cargo de provimento efetivo no Estado do Tocantins, após regular aprovação em concurso público, tomou posse e entrou em exercício em cargo público diverso, vinculado ao mesmo ente federativo. Para sua decepção, foi inabilitada no estágio probatório relativo ao último cargo. Nesse caso, Maria deve ser:','{"A": "reintegrada ao cargo anterior, desde que este último esteja vago;", "B": "exonerada, cessando o seu vínculo funcional com o poder público;", "C": "readaptada ao cargo anterior, caso assim requeira, desde que este último esteja vago;", "D": "reconduzida ao cargo anterior e, se este último tiver sido provido, será aproveitada em outro;", "E": "revertida ao cargo anterior, ainda que este último esteja ocupado, o que pressupõe a prévia colocação em disponibilidade do respectivo ocupante. CONHECIMENTOS ESPECÍFICOS"}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',36,'Língua Portuguesa',null,'Um teólogo inglês proferiu a seguinte frase: “O pessimista se queixa do vento, / o otimista espera que ele mude / e o realista ajusta as velas”. Sobre os componentes dessa frase, é correto afirmar que:','{"A": "o pessimista, o otimista e o realista mostram, diante de realidades diferentes, posicionamentos também diversos;", "B": "o pronome “ele” se refere, por coesão, ao termo “pessimista”, na frase anterior;", "C": "o segmento “ajusta as velas” traz sentido mais específico às frases anteriores;", "D": "os segmentos marcados nessa frase mostram perfeito paralelismo em sua organização sintática;", "E": "a conjunção E mostra sentido explicativo."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',37,'Língua Portuguesa',null,'Nas opções abaixo, apresentam-se paráfrases da frase anterior do teólogo inglês; a opção em que é seguida rigorosamente a mesma estruturação significativa da frase original, é:','{"A": "O pessimista se queixa da guerra, o otimista espera que ela termine e o realista prepara seus exércitos;", "B": "O pessimista se queixa dos preços dos alimentos, o otimista espera que eles caiam e o realista procura produtos substitutos;", "C": "O pessimista se queixa da demora do ônibus para o trabalho, o otimista espera que ele chegue rápido e o realista pensa em pegar um táxi;", "D": "O pessimista se queixa do vento forte, o otimista espera que ele perca a intensidade e o realista fecha a barraca na areia da praia;", "E": "O pessimista se queixa do preço da gasolina, o otimista espera que ele diminua e o realista decide abastecer com álcool."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',38,'Língua Portuguesa',null,'Um poeta romano escreveu: “Ninguém olha para o que há diante dos pés. Todos olham para as estrelas”. Considerando-se que se trata de um pensamento moralizante, o sentido da frase é o de que os homens:','{"A": "desprezam o presente em função de um futuro promissor;", "B": "não observam a realidade, preferindo os sonhos;", "C": "consideram os obstáculos da vida, mas preferem a poesia;", "D": "em lugar de pessimistas, procuram ser realistas;", "E": "encontram problemas na vida, mas os resolvem facilmente. Tipo 1 – Branca – Página 12"}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',39,'Língua Portuguesa',null,'Numa fala de uma peça de teatro, um comediante holandês disse a seguinte frase: “É difícil encarar a realidade quando ela tem muitas faces”. A forma adequada de reescrever-se essa frase é:','{"A": "É difícil que encaremo-nos a realidade quando ela tem muitas faces;", "B": "É difícil que se encarasse a realidade quando ela tem muitas faces;", "C": "É difícil que a realidade seja encarada quando ela tem muitas faces;", "D": "É difícil a realidade ter sido encarada quando ela tem muitas faces;", "E": "É difícil que não se encare a realidade quando ela é multifacetada."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',40,'Língua Portuguesa',null,'A frase abaixo que NÃO mostra, como as demais, a possibilidade de diferentes pontos de vista, é:','{"A": "Nós todos vivemos sob o mesmo céu, mas não temos todos o mesmo horizonte;", "B": "O que a lagarta chama de fim do mundo, o mestre chama de borboleta;", "C": "O vento é o mesmo, mas sua resposta é diferente em cada folha;", "D": "É preciso aceitar que um dia você é o pombo e outros dias você é a estátua;", "E": "Se há uma opinião, fatos serão achados para apoiá-la."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',41,'Língua Portuguesa',null,'Há diferentes exemplos de intertextualidade. Todas as frases abaixo mostram intertextualidade; a opção em que é exemplificada uma alusão, é:','{"A": "Minha terra tinha palmeiras, mas já mataram todos os sabiás;", "B": "Já que todos devem trabalhar e meus netos vão ficar sozinhos, digam a todos eles que fico;", "C": "É o que dizia meu pai: “Problema que se resolve com dinheiro, não é problema”;", "D": "O lema da campanha já era conhecido: “Senta a pua!”;", "E": "A nova cozinheira fazia pratos horríveis, mas dizia como o famoso chefe francês “Marravilha!”."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',42,'Língua Portuguesa',null,'A frase abaixo cuja estruturação apela para a polissemia de um vocábulo, é:','{"A": "O sábio lê livros, mas também a vida;", "B": "Jornalismo consiste em comprar papel branco a dois centavos e vendê-lo a dez;", "C": "Bebendo-se um pouco de vinho, a inteligência aparece;", "D": "Quanto mais dividimos os obstáculos, mais fácil é vencê-los;", "E": "Champanhe: borbulhas espumantes, brancas como as pérolas de Cleópatra."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',43,'Língua Portuguesa',null,'Nos atos de comunicação, deve-se levar em conta a situação; a frase abaixo em que o significado do termo destacado depende da situação de comunicação, é:','{"A": "Amanhã começam as obras em nosso bairro;", "B": "Hoje, dia 15 de novembro, festeja-se a República;", "C": "Ainda se passeia muito pelas ruas do Rio;", "D": "Eles, o autor e o leitor, se merecem;", "E": "O quadro “O Dormitório” de Van Gogh é magnífico."}'::jsonb,'A',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',44,'Língua Portuguesa',null,'A frase abaixo que é modalizada no sentido de transmitir certeza absoluta, é:','{"A": "Fumar prejudica a saúde;", "B": "Certamente eles devem ter saído há pouco;", "C": "É claro que os maus alunos não conseguiram aprovação;", "D": "Os cidadãos urbanos respiram ar muito poluído;", "E": "A língua inglesa é predominante no Canadá."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',45,'Língua Portuguesa',null,'A frase abaixo que NÃO mostra nenhuma estrutura de caráter explicativo, é:','{"A": "Como fazer esse bolo? Seguindo a receita que está no livro;", "B": "Não é errado ter opiniões firmes. Errado é não ter nada além disso;", "C": "Os pesquisadores dos laboratórios Bell (Estados Unidos) inventaram o transistor, elemento de base dos computadores modernos;", "D": "Os garis são como as formigas: trabalham em conjunto e de forma organizada;", "E": "Todos querem viver muito tempo, mas ninguém quer ficar velho."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',46,'Língua Portuguesa',null,'O registro de um texto é constituído pelo conjunto de elementos expressivos que constroem um tom produtor de uma emoção particular no destinatário. Os principais registros são: o cômico, o satírico, o trágico, o lírico, o épico, o fantástico, o polêmico e o patético. A opção abaixo que exemplifica o registro satírico, é:','{"A": "Eis a sabedoria: gostar do vinho, da beleza e da primavera divina, isto é o bastante; o resto é futilidade;", "B": "Amor, dinheiro e lua, quando param de crescer, começam logo a diminuir;", "C": "Mais vale um galo no terreiro do que dois na testa;", "D": "Quem gosta de viver sozinho está sempre em má companhia;", "E": "Você não pode dizer quem está nadando nu até a maré baixar."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',47,'Língua Portuguesa',null,'Uma das características da textualidade é a coerência; a opção abaixo que mostra coerência, é:','{"A": "Um contrato verbal não vale o papel em que está escrito;", "B": "Quem tudo quer, tudo perde;", "C": "Nunca faça previsões, especialmente para o futuro;", "D": "O crítico de futebol está sempre certo porque só opina quando o jogo termina;", "E": "Não seja supersticioso – dá azar. Tipo 1 – Branca – Página 13"}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',48,'Língua Portuguesa',null,'Observe o texto descritivo a seguir. “Em 1809, Dona Margarida, que não revelava a sua idade, tinha 75 anos. Conhecida em seu tempo como a bela quitandeira, ela era uma dessas raras mulheres que o tempo respeita, e devia a uma excelente constituição física o privilégio de manter uma beleza que, entretanto, não resistiria a um exame mais profundo.” A função da descrição nesse segmento é:','{"A": "documental, pois registra hábitos de uma época;", "B": "explicativa, pois justifica a psicologia do personagem;", "C": "metafórica, pois mostra uma outra realidade;", "D": "caracterizadora, pois estrutura um personagem;", "E": "argumentativa, pois defende um ponto de vista."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',49,'Língua Portuguesa',null,'Observe o segmento de narrativa a seguir. “Todos os passageiros corriam pela plataforma, pois o trem já havia chegado. Alguns já estavam instalados nos camarotes e observavam a confusão pela janela. Tenha juízo, meu filho. Telefone quando chegar. O trem apitou três vezes e começou lentamente a deslocar-se.” Esse segmento exemplifica uma maneira de inserir palavras numa narrativa, denominada:','{"A": "discurso indireto livre;", "B": "diálogo;", "C": "discurso indireto;", "D": "citação;", "E": "discurso direto."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',50,'Língua Portuguesa',null,'O segmento textual abaixo que deve ser classificado como argumentativo, é:','{"A": "Faça o que eu digo, mas não faça o que eu faço;", "B": "Viver é morrer aos poucos;", "C": "Numerosos são aqueles para quem a arte não passa de uma distração;", "D": "Como dizia o profeta, tudo na vida tem um fim e devemos preparar-nos para ele;", "E": "Os jovens costumam repetir o que dizem os pais e os professores."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',51,'Língua Portuguesa',null,'A opção abaixo que mostra um paradoxo, é:','{"A": "Eu admitiria facilmente que a paz pública é um grande bem; mas não posso esquecer que é por meio da ordem que os povos chegam à tirania;", "B": "O que foi seguido por todos, sempre e em todos os lugares, tem todas as chances de ser falso;", "C": "Atualmente, é muito comum que a maioria dos ciclistas das grandes provas estejam dopados;", "D": "Os atores cinematográficos certamente alcançam mais sucesso que os teatrais;", "E": "Os jornais impressos e televisivos fazem-nos viver os grandes acontecimentos mundiais."}'::jsonb,'B',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',52,'Língua Portuguesa',null,'A opção abaixo que exemplifica um raciocínio analógico, é:','{"A": "A Internet permite nossa comunicação rápida com muitas pessoas ao redor do mundo;", "B": "Choveu muito durante toda a madrugada; as ruas devem estar inundadas;", "C": "Da mesma forma que nos aprofundamos em ciências, devíamos aprofundar-nos em humanidades;", "D": "Depois dos 80, tudo nos lembra outra coisa;", "E": "Quem não levar dinheiro na carteira, que ponha mel nos lábios."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',53,'Língua Portuguesa',null,'Uma frase pode apresentar-se em formas variadas; a frase abaixo que apresenta uma forma enfática, colocando em destaque um de seus elementos, é:','{"A": "Eu não estarei presente amanhã na conferência;", "B": "Ainda existem muitas injustiças no mundo;", "C": "Teu pai é que vai ficar contente;", "D": "Os carros foram levados rapidamente;", "E": "Dois milhões de espectadores viram o filme."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',54,'Língua Portuguesa',null,'Todas as frases abaixo trazem as formas verbais no modo imperativo; a frase em que esse imperativo expressa um desejo, é:','{"A": "Fiquem quietos para as fotos!", "B": "Tragam-me o prisioneiro!", "C": "Mostre-me o seu desenho!", "D": "Não façam mais isso!", "E": "Pare de fumar!"}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',55,'Língua Portuguesa',null,'Todas as frases iniciais abaixo sofreram modificações; aquela opção em que a modificação transformou a frase para a forma impessoal, é:','{"A": "Comprei aquele carro ontem / Aquele carro foi comprado por mim ontem;", "B": "Não aceitamos esse julgamento parcial / Esse julgamento parcial, não o aceitamos;", "C": "Queremos transformar o mundo / Queremos a transformação do mundo;", "D": "Não desejamos nada alheio / Não se deseja nada alheio;", "E": "Não aprecio este tipo de música / Detesto este tipo de música. Tipo 1 – Branca – Página 14"}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',56,'Língua Portuguesa',null,'Observe a seguinte tese: O conflito de gerações é inicialmente a consequência de uma dificuldade de comunicação. Entre as opções abaixo, aquela que apresenta um exemplo, e não um argumento para a defesa dessa tese, é:','{"A": "Se os jovens e seus pais mostram às vezes dificuldades de comunicação, isso ocorre em função de uma diferença de educação;", "B": "Hoje, os jovens vivem em instabilidade referente a empregos, o que inquieta seus pais, habituados a uma vida mais estável;", "C": "Os vocábulos adotados pelos jovens são trazidos do inglês e constituem um dialeto no qual os jovens se reconhecem melhor do que as antigas gerações;", "D": "Se a comunicação é difícil entre as gerações, isso ocorre porque elas não falam a mesma língua;", "E": "Num romance francês, o jovem personagem e seu pai não se dão porque este último se recusa a aceitar a ideia do filho de não ser um carpinteiro como ele."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',57,'Língua Portuguesa',null,'Observe o texto a seguir. “O artista defendeu o direito de as pessoas seguirem a moda, mas reconhece que ela é muitas vezes ridícula pelos exageros que comete.” Trata-se de um texto argumentativo que emprega a seguinte estratégia:','{"A": "defesa da tese, levando em conta a força de uma tese oposta;", "B": "refutação de uma tese oposta, criticando os argumentos adversos;", "C": "debate da tese, mostrando paralelamente argumentos favoráveis e desfavoráveis;", "D": "afirmação de uma tese, reconhecendo aspectos positivos na tese contrária;", "E": "apresentação de argumentos de autoridade para a defesa de sua tese."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',58,'Língua Portuguesa',null,'O desenvolvimento de uma argumentação segue, na forma mais frequente, uma progressão coerente em direção a uma conclusão. Os componentes dessa progressão podem estar articulados por conectores. As opções abaixo mostram o tipo de relação lógica entre os componentes, assim como conectores adequados para a expressão dessa relação. A opção em que a relação lógica é seguida de pelo menos um conector inadequado, é:','{"A": "relação de adição: além disso, não só... mas também;", "B": "relação de oposição: todavia, no entretanto;", "C": "relação de comparação: do mesmo modo, assim como;", "D": "relação de concessão: ainda que, conquanto;", "E": "relação de conclusão: logo, portanto."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',59,'Língua Portuguesa',null,'A frase abaixo foi redigida sem a pontuação original: “Amigo é aquele que sabe tudo a seu respeito e mesmo assim ainda gosta de você”. A forma de reescrever essa frase com a sua pontuação adequada, é:','{"A": "Amigo é aquele, que sabe tudo a seu respeito, e mesmo assim, ainda gosta de você.", "B": "Amigo é aquele, que sabe tudo a seu respeito, e, mesmo assim, ainda gosta de você.", "C": "Amigo é aquele que sabe tudo a seu respeito, e, mesmo assim, ainda gosta de você.", "D": "Amigo é aquele, que sabe tudo a seu respeito, e, mesmo assim ainda gosta de você.", "E": "Amigo é aquele que sabe tudo a seu respeito, e mesmo assim, ainda gosta de você."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',60,'Língua Portuguesa',null,'Em todas as frases abaixo há uma imprecisão nos dados numéricos, EXCETO em uma; a opção em que não há imprecisão, é:','{"A": "Havia na palestra cerca de 200 assistentes;", "B": "Minha ex-namorada já tem seus 60 anos;", "C": "O Brasil tem perto de 200 milhões de habitantes;", "D": "O Havaí tem mais de 50 vulcões;", "E": "Sua certidão registra 70 anos de vida."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',61,'Língua Portuguesa',null,'Uma das principais características do texto informativo é a sua clareza; um dos meios para conseguir clareza é a utilização da ordem direta nas frases. A frase abaixo que está na ordem direta, é:','{"A": "O Natal é a época em que as pessoas ficam sem dinheiro;", "B": "Com os amigos que tenho, não preciso de inimigos;", "C": "É impossível ensinar um gato a não pegar passarinhos;", "D": "Antes um pássaro a voar que dois na mão;", "E": "Pisado, o menor verme se revira."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',62,'Língua Portuguesa',null,'Como os textos informativos se preocupam bastante com a clareza, alguns deles traduzem as siglas neles contidas entre parênteses. A opção abaixo em que essa “tradução” está correta, é:','{"A": "O MST (Movimento dos Sem-Trabalho) exige reformas na legislação trabalhista;", "B": "O inquilino jurou pagar o IPTU (Imposto Predial e Territorial Urbano) até o final do mês;", "C": "O chefe do FMI (Fundação Mundial de Intercâmbio) visitará o país ainda este ano;", "D": "A Rússia ficou preocupada com a filiação da Ucrânia à OTAN (Organização do Tratado Americano das Nações);", "E": "A ONU (Organização das Nações Unificadas) condenou a guerra. Tipo 1 – Branca – Página 15"}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',63,'Língua Portuguesa',null,'Aedes aegypti é uma forma latina que designa o mosquito causador da dengue (“mosquito do Egito”). O latinismo cujo significado está corretamente indicado, entre as opções abaixo, é:','{"A": "Em época de crise, o lazer fica adiado sine die / para uma data já marcada;", "B": "Para um debate é importante ter a priori algumas informações / de forma privilegiada;", "C": "O esgoto in natura é jogado em local distante / sem tratamento;", "D": "Algumas populações respeitam seu habitat / o modelo habitacional;", "E": "Não houve quorum suficiente para a votação do projeto / debate público."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',64,'Língua Portuguesa',null,'“O policial olha pela janela a menina correndo, alguns homens que a perseguiam e pessoas em fuga.” Se o autor da frase tivesse preocupação com o paralelismo na construção dessa frase, sua forma seria:','{"A": "O policial olha pela janela a menina correndo, alguns homens perseguindo-a e pessoas fugindo;", "B": "O policial olha pela janela a menina que corria, alguns homens que a perseguiam e pessoas em fuga;", "C": "O policial olha pela janela a menina em corrida, alguns homens que a perseguiam e pessoas em fuga;", "D": "O policial olha pela janela a menina correndo, alguns homens que a perseguiam e pessoas fugindo;", "E": "O policial olha pela janela a menina correndo, alguns homens que a perseguiam e pessoas que fugiam."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',65,'Língua Portuguesa',null,'Os slogans publicitários sempre se apoiam em alguns valores sociais para o sucesso de venda dos produtos anunciados. O slogan abaixo cujo valor social está corretamente identificado, é:','{"A": "Hortifrúti: a natureza a seu alcance / defesa do meio ambiente;", "B": "Faça suas compras aqui, uma loja de seu bairro / intimidade;", "C": "As impressoras FACIT imprimem mais rápido / economia;", "D": "Compre Chevrolet e se sinta nas nuvens / beleza;", "E": "Use agendas Ediouro / organização pessoal."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',66,'Língua Portuguesa',null,'Observe o texto narrativo a seguir. “Devo suspender momentaneamente a narrativa para explicar o título dado a esse romance, algo que já deveria ter sido feito.” Nesse caso, a interrupção da narrativa deve ser classificada como:','{"A": "interpelação direta ao leitor;", "B": "referência ao já conhecido por autor e leitor;", "C": "utilização de travessões ou parênteses;", "D": "comentário sobre processos de narração;", "E": "mudança de gênero textual."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',67,'Língua Portuguesa',null,'Todos sabemos que o texto descritivo utiliza muitas formas de adjetivação; entre as opções abaixo, aquela que tem a forma de adjetivação corretamente identificada, é:','{"A": "Van Gogh era o pintor! / adjetivo;", "B": "Os alunos que estudam têm chance de sucesso / oração adjetiva;", "C": "Morava num casebre no final da rua / comparação;", "D": "Ele não escreveu uma história parecida? / forma reduzida;", "E": "Havia no ar um perfume masculino / afixos."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',68,'Língua Portuguesa',null,'“O professor olhou o livro de capa grossa e colorida sobre a mesa, pegou-o, virou-o ao contrário e pôde observar a mesma cor na contracapa.” Sobre essa pequena descrição, é correto afirmar que:','{"A": "o observador e o objeto descrito estão imóveis;", "B": "o observador está em movimento e o objeto descrito, imóvel;", "C": "os dados descritivos são de base visual e tátil;", "D": "o observador e o objeto descrito estão em movimento;", "E": "o observador está imóvel e o objeto descrito, em movimento."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',69,'Língua Portuguesa',null,'O ato de descrever sofre uma série de limitações; no texto a seguir, por exemplo, o observador não pôde descrever com exatidão o animal que via. “O menino entrou no Zoológico, soltou-se da mão da mãe, e logo na primeira jaula viu um animal estranho: aproximou-se da grade e viu que ele possuía patas grandes e fortes na traseira, mas patas menores na parte dianteira ou superior e uma espécie de corte no pelo, na altura da barriga, onde havia um filhote”. Nesse caso, a descrição incompleta se deve:','{"A": "a limitações da visão do observador;", "B": "ao distanciamento entre o observador e o animal;", "C": "à falta de conhecimento do observador;", "D": "a problemas psicológicos do observador;", "E": "ao fato de o objeto ser um espécime único no mundo."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',70,'Língua Portuguesa',null,'“Existem dois lados em cada problema: o nosso lado e o lado muito errado.” Nessa frase há uma forma de superlativo (muito errado); a frase abaixo em que NÃO há qualquer forma de superlativo, é:','{"A": "É bem difícil conviver com um pessimista;", "B": "O otimismo exagerado é um defeito chatinho;", "C": "Fatos são coisas teimosas pra burro;", "D": "Os legumes estão baratos;", "E": "O homem estava algo abatido devido à doença. Tipo 1 – Branca – Página 16 DISCURSIVA 1 Transforme as frases verbais abaixo em frases nominais a fim de formar títulos para reportagens de jornais impressos: a) A classe política declarou-se satisfeita depois da publicação do calendário eleitoral. b) O Congresso, após o período de recesso, retomou suas atividades. c) Espera-se um debate acalorado entre candidatos à presidência. d) Canais de TV fixam datas para apresentarem a nova programação. Valor: 15 pontos Máximo de 15 linhas. 2 Em cada uma das frases abaixo, elimine as marcas de enunciação de modo a produzir frases adequadas aos tipos solicitados entre parênteses. a) Deveríamos incentivar o ensino musical entre alunos do ensino médio. (tipo de frase na voz passiva com auxiliar) b) Eu desconfio de todos esses produtos da indústria agroalimentar. (tipo injuntivo de frase) c) Lastimamos não ser mais ampla a solidariedade entre os povos. (tipo impessoal de frase) d) Esperam os cientistas serem eficientes as vacinas contra a varíola dos macacos. (tipo enfático, com a valorização de um termo) Valor: 15 pontos Máximo de 15 linhas. Tipo 1 – Branca – Página 17 RASCUNHO - Prova Discursiva - Questão 1 1 5 10 15 RASCUNHO - Prova Discursiva - Questão 2 1 5 10 15"}'::jsonb,'D',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','alternativa muito longa: pode conter texto de outra questão; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno')
